    public void init()
    {
        next init();

        Common commonTable = element.args().record();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
            && commonTable.TableId == tableNum(SalesTable))
        {
            this.initSalesOrderPricingAttributes(commonTable);
        }
    }

    /// <summary>
    /// Instiantiate attributes on a sales order.
    /// </summary>
    /// <param name = "_salesTable">The row of the sales table.</param>
    private void initSalesOrderPricingAttributes(SalesTable _salesTable)
    {
        GUPParameters gupParameters;
        RetailSalesTableInstanceValue retailSalesTableInstanceValue;
        Set attributeGroupRecIdSet = new Set(Types::Int64);

        select firstonly SalesOrderAttributeGroup from gupParameters
                where gupParameters.DataAreaId == _salesTable.DataAreaId;

        attributeGroupRecIdSet.add(gupParameters.SalesOrderAttributeGroup);

        // Get the sales table instance value
        retailSalesTableInstanceValue = RetailSalesTableInstanceValue::findOrCreate(_salesTable.SalesId, _salesTable.DataAreaId);

        //this.initAttributeValues(attributeGroupRecIdSet, retailSalesTableInstanceValue.RecId);
    }
